local item_lib = require("items")
local rescued = false
function event_say(e)
  if e.message:findi("hail") then
    e.self:Say("Hurry! There's not much time. Give me the key and show me proof that you are a friend sent to rescue me...")
  end
end
function event_trade(e)
  local escort = eq.get_entity_list():GetMobByNpcTypeID(2000944)
  if not rescued and not escort.valid and item_lib.check_turn_in(e.trade, {item1 = 1046, item2 = 30162}) then
    rescued = true
    e.self:Say("I thought I was a dwarfskin rug there for a minute! Thank Brell for your help stranger! Now cover me while I make good my escape. I am weakened and cannot endure much more.")
    e.other:SummonItem(30162)
    -- A new rescue supersedes an unclaimed earlier reward form, as in TAKP.
    eq.depop(2000945)
    eq.unique_spawn(2000944, 0, 0, e.self:GetX(), e.self:GetY(), e.self:GetZ(), e.self:GetHeading())
    eq.depop_with_timer()
  end
  item_lib.return_items(e.self, e.other, e.trade)
end
